INSERT INTO `odoo_pages` VALUES (1,'Official Partner','United Arab Emirates','Transform Your Business with Official Odoo ERP in Dubai','Unify your Accounting, HR & WPS Payroll, CRM, Inventory, and Manufacturing into one intuitive platform. Fully pre-configured for UAE FTA 5% VAT, Central Bank WPS SIF files, and bilingual operations.','+971 50 369 2131','info@hvaclinic.com','[\"FTA 5% VAT Ready\", \"UAE WPS SIF Export\", \"Arabic & English UI\", \"5 UAE Branch Offices\"]','[{\"id\": \"accounting\", \"desc\": \"Automate your 5% UAE VAT calculations, generate FTA Audit Files (FAF), and reconcile seamlessly with UAE Central Bank authorized banks.\", \"icon\": \"receipt\", \"name\": \"Accounting & UAE VAT\", \"badge\": \"FTA Compliant\", \"features\": [\"Standard UAE Chart of Accounts pre-configured\", \"Automated 5% VAT computation & FTA Tax Return reports\", \"Bilingual Arabic-English Tax Invoices with QR code\", \"Direct bank feeds for ENBD, FAB, ADCB, and Mashreq\", \"Multi-currency handling (AED, SAR, USD, EUR, GBP)\"], \"headline\": \"UAE FTA-Compliant Bilingual Accounting & E-Invoicing\"}, {\"id\": \"hrms\", \"desc\": \"Generate Wage Protection System (WPS) SIF files in one click and calculate End of Service Gratuity (EOSB) strictly per UAE Labour Law 33.\", \"icon\": \"users\", \"name\": \"HR & WPS Payroll\", \"badge\": \"WPS Ready\", \"features\": [\"One-click UAE Central Bank SIF format export\", \"Automated Gratuity (EOSB) accruals per UAE Labour Law\", \"Emirates ID, Visa, Passport, and labour card expiry alerts\", \"Biometric device integration & mobile GPS geofencing\", \"Employee Self-Service (ESS) for leaves, loans, and expenses\"], \"headline\": \"MOHRE-Compliant UAE Payroll & Workforce Management\"}, {\"id\": \"crm\", \"desc\": \"Connect WhatsApp Cloud API directly to Odoo CRM leads, visualize deal stages, automate quotations, and track sales rep performance.\", \"icon\": \"target\", \"name\": \"CRM & Sales Automation\", \"badge\": \"WhatsApp Cloud\", \"features\": [\"Direct WhatsApp Business Cloud API integration\", \"Visual Kanban pipelines with deal probability scoring\", \"Automated quotation generation with digital e-signatures\", \"Sales team commissions and target dashboards\", \"Automated email & WhatsApp follow-up drip sequences\"], \"headline\": \"Omnichannel Sales Acceleration for UAE Sales Teams\"}, {\"id\": \"inventory\", \"desc\": \"Track stock movements across UAE freezones and mainland facilities with double-entry inventory, batch/lot tracking, and landed costs.\", \"icon\": \"boxes\", \"name\": \"Inventory & Supply Chain\", \"badge\": \"Multi-Warehouse\", \"features\": [\"Mainland & Freezone (JAFZA, DAFZA, HFZA) warehouse routing\", \"Landed costs calculation including customs duties & freight\", \"Batch, Lot, and Expiry date tracking with FIFO/LIFO rules\", \"Barcode & QR code mobile scanner integration\", \"Automated reordering rules to eliminate stockouts\"], \"headline\": \"Multi-Location Warehousing for Mainland & Freezone Operations\"}, {\"id\": \"mrp\", \"desc\": \"Coordinate work orders, multi-level bill of materials, subcontractor operations, and preventive equipment maintenance.\", \"icon\": \"cog\", \"name\": \"Manufacturing (MRP)\", \"badge\": \"Smart Factory\", \"features\": [\"Multi-level Bill of Materials (BOM) & kit management\", \"Work center capacity planning and routing schedules\", \"Subcontracting & third-party job work tracking\", \"Real-time shop floor control tablet interface\", \"Quality checkpoints and waste reduction analytics\"], \"headline\": \"Precision Manufacturing, BOMs & Work Orders\"}, {\"id\": \"pos\", \"desc\": \"Fully integrated POS that operates online and offline, synchronizing inventory instantly across physical stores and web shops.\", \"icon\": \"shopping-cart\", \"name\": \"Point of Sale (POS)\", \"badge\": \"Offline Capable\", \"features\": [\"Works 100% offline with automatic cloud re-sync\", \"Integrated payment terminals (Network Intl, Telr, Geidea)\", \"Customer loyalty programs, gift cards, and coupons\", \"Kitchen display system (KDS) & table management for F&B\", \"Unified inventory across physical branches and e-commerce\"], \"headline\": \"Blazing-Fast Retail & Restaurant POS for the GCC\"}]','[{\"desc\": \"Turnkey deployment from requirement discovery and business blueprint to configuration, testing, and successful UAE go-live.\", \"icon\": \"rocket\", \"title\": \"Odoo Implementation\"}, {\"desc\": \"Tailored Python module development and workflow extensions to accommodate your organization\'s unique operational rules.\", \"icon\": \"code-2\", \"title\": \"Customization & Module Dev\"}, {\"desc\": \"Secure extraction, sanitization, and migration of historical records from Tally, SAP, Oracle, Zoho, QuickBooks, or Excel.\", \"icon\": \"database\", \"title\": \"Legacy ERP Data Migration\"}, {\"desc\": \"API bridges to payment gateways, UAE courier services (Aramex, DHL), biometric scanners, and WhatsApp Business API.\", \"icon\": \"workflow\", \"title\": \"UAE Third-Party Integrations\"}, {\"desc\": \"Role-based, bilingual training for executives, accountants, warehouse supervisors, and sales teams in Dubai or on-site.\", \"icon\": \"graduation-cap\", \"title\": \"Corporate Training & Enablement\"}, {\"desc\": \"Dedicated Dubai helpdesk with guaranteed response times, proactive updates, bug resolution, and version migrations.\", \"icon\": \"headphones\", \"title\": \"24/7 Managed Support & SLA\"}]','[{\"a\": \"Yes. Our Odoo UAE deployment is strictly aligned with UAE FTA requirements. It calculates 5% VAT automatically, generates bilingual Tax Invoices with mandatory QR codes, handles reverse charges, and exports Federal Tax Authority Audit Files (FAF) for seamless quarterly return filings.\", \"q\": \"Is Odoo fully approved and compliant with UAE Federal Tax Authority (FTA) regulations?\"}, {\"a\": \"Yes, in a single click. Our UAE payroll module formats employee wages into the standard UAE Central Bank .SIF file format, fully compatible with WPS agents like Al Ansari Exchange, ENBD, FAB, ADCB, and Mashreq.\", \"q\": \"Can Odoo generate Wage Protection System (WPS) SIF files for UAE banks?\"}, {\"a\": \"We execute a 4-phase data migration strategy: extraction, cleaning & reconciliation, staging import, and final trial balance verification. Your historical ledgers, open customer balances, stock valuation, and supplier dues are ported with zero downtime.\", \"q\": \"How does Recovery Data handle migration from our existing ERP (Tally, QuickBooks, Zoho, SAP)?\"}, {\"a\": \"Standard deployments (Accounting, Sales, Purchase & Inventory) usually take between 3 to 6 weeks. Complex enterprise implementations with custom manufacturing, POS, and HRMS take 8 to 12 weeks with full user acceptance testing.\", \"q\": \"How long does a typical Odoo implementation take for a UAE business?\"}]',NULL,'odoo partner dubai','Official Odoo Partner Dubai & UAE | Certified ERP Implementation','Official Odoo Partner in UAE. Certified Odoo ERP implementation, FTA-compliant VAT accounting, UAE WPS payroll, and customization across Dubai & UAE.','odoo partner dubai, odoo uae, official odoo partner uae, odoo erp dubai, odoo implementation uae, odoo vat accounting fta, odoo wps payroll dubai',95,90,1,'2026-10-08 04:42:41','2026-10-16 14:22:52');
/*!40000 ALTER TABLE `odoo_pages` ENABLE KEYS */;
