INSERT INTO `pages` VALUES (27,9,'Home – HVAC Clinic – Rental Chiller – Rental Power','home','		<div data-elementor-type=\"wp-page\" data-elementor-id=\"627\" class=\"elementor elementor-627\">\n				<div class=\"elementor-element elementor-element-65ed189 e-flex e-con-boxed e-con e-parent\" data-id=\"65ed189\" data-element_type=\"container\" data-e-type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">\n					<div class=\"e-con-inner\">\n				<div class=\"elementor-element elementor-element-339c148 elementor-widget elementor-widget-text-editor\" data-id=\"339c148\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p>Your Trusted HVAC Partner Across the UAE.</p>								</div>\n				</div>\n				<div class=\"elementor-element elementor-element-aed07f7 elementor-widget__width-initial elementor-widget-tablet__width-inherit elementor-widget elementor-widget-heading\" data-id=\"aed07f7\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"heading.default\">\n				<div class=\"elementor-widget-container\">\n					<h2 class=\"elementor-heading-title elementor-size-default\">Welcome to HVAC</h2>				</div>\n				</div>\n					</div>\n				</div>\n		<div class=\"elementor-element elementor-element-25851a1 e-flex e-con-boxed e-con e-parent\" data-id=\"25851a1\" data-element_type=\"container\" data-e-type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">\n					<div class=\"e-con-inner\">\n		<div class=\"elementor-element elementor-element-c275e75 e-flex e-con-boxed e-con e-child\" data-id=\"c275e75\" data-element_type=\"container\" data-e-type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">\n					<div class=\"e-con-inner\">\n				<div class=\"elementor-element elementor-element-b654f0a elementor-widget elementor-widget-heading\" data-id=\"b654f0a\" dat